import { forwardRef, type ImgHTMLAttributes } from 'react';

export interface PlateImageProps extends ImgHTMLAttributes<HTMLImageElement> {
  /** JPEG fallback URL (Vite asset import). */
  src: string;
  /** Optional WebP variant URL (Vite asset import of the .webp sibling). */
  webp?: string;
  /** Optional AVIF variant URL (Vite asset import of the .avif sibling). */
  avif?: string;
  alt: string;
}

/**
 * Plate image renderer (design-system audit 2026-10-22, rec 7).
 *
 * Serves the modern-format variants generated by
 * `scripts/generate-image-variants.mjs` through a `<picture>` element:
 * AVIF first, WebP second, JPEG as the universal fallback. Browsers pick the
 * first `<source>` whose type they support; crawlers and ancient clients fall
 * through to the JPEG `<img>`, which also carries the alt text.
 *
 * Registries that pass plain `src` strings (engines.ts, engineBlogs.ts,
 * media/registry.ts) keep working unchanged — pass `webp`/`avif` only where
 * the render site can import the siblings.
 */
export const PlateImage = forwardRef<HTMLImageElement, PlateImageProps>(
  function PlateImage({ src, webp, avif, alt, loading = 'lazy', decoding = 'async', ...rest }, ref) {
    return (
      <picture>
        {avif && <source srcSet={avif} type="image/avif" />}
        {webp && <source srcSet={webp} type="image/webp" />}
        <img ref={ref} src={src} alt={alt} loading={loading} decoding={decoding} {...rest} />
      </picture>
    );
  },
);
